public class WorkerTask implements Runnable {
    @Override
    public void run() {
        try {
            while (!Thread.currentThread().isInterrupted()) {
                // Perform heavy computation or check a blocking structure
                doWork();

                // Simulating a cancellable wait state
                Thread.sleep(1000);
            }
        } catch (InterruptedException e) {
            // Thread was interrupted during sleep(); flag is now cleared by JVM.
            // Best practice: restore the flag so callers up the stack know.
            Thread.currentThread().interrupt();
        } finally {
            cleanupResources();
        }
    }

    private void doWork() {
        // Check explicitly if computation is non-blocking
        if (Thread.interrupted()) {
            // Thread.interrupted() clears the flag. We must handle or restore it.
            throw new RuntimeException(new InterruptedException());
        }
    }

    private void cleanupResources() {
        // Release JDBC connections, sockets, or file handles safely
    }
}
